```{.r .cell-code}
library(gt)

site_table <- tibble(
  Site = c(
    "Arikaree River, Colorado",
    "Caribou Creek, Alaska",
    "Lewis Run, Virginia"
  ),
  Climate = c(
    "Semi-arid",
    "Subarctic",
    "Temperate"
  ),
  `Surrounding landscape` = c(
    "Grasslands and agriculture",
    "Taiga and permafrost",
    "Fields, pastures, woodlands and small ponds"
  ),
  `Stream conditions` = c(
    "Intermittent; can dry in summer",
    "Perennial; ice-covered in winter",
    "Perennial"
  ),
  Urbanised = c(
    "No",
    "No",
    "Yes"
  )
)

site_table |>
  gt() |>
  tab_header(
    title = "Three streams, three different environments",
    subtitle = "The study compared streams across contrasting climates and landscapes"
  ) |>
  cols_width(
    Site ~ px(180),
    Climate ~ px(100),
    `Surrounding landscape` ~ px(220),
    `Stream conditions` ~ px(190),
    Urbanised ~ px(90)
  ) |>
  tab_source_note(
    source_note = md("Source: Kermorvant et al. (2023).")
  )
```

